# kr_pit_fixed.py (verified in v10_fixed_test.py)
from __future__ import annotations
import os, re, time
import numpy as np
import pandas as pd
import requests
MARCAP_URL = "https://raw.githubusercontent.com/FinanceData/marcap/master/data/marcap-{year}.parquet"
COLS = ["Date","Code","Name","Market","MarketId","Dept","Open","High","Low","Close","Changes","ChangesRatio","Volume","Amount","Marcap","Stocks","Rank"]
_SPAC_RE = re.compile(r"스팩|기업인수목적|SPAC", re.I)
_NONSTOCK_RE = re.compile(r"리츠$|^이리츠|REIT|부동산투자회사|인프라투융자|맥쿼리인프라|발해인프라|맵스리얼티|선박투자|유전"
                          r"|\d+호$|베트남개발|한국패러랠|하나니켈", re.I)
_ADMIN_DEPT = ("관리종목", "투자주의환기")

def download_marcap(years, cache_dir, refresh_current=True, pause=0.3):
    os.makedirs(cache_dir, exist_ok=True); paths, this_year = [], pd.Timestamp.today().year
    for y in years:
        path = os.path.join(cache_dir, f"marcap-{y}.parquet")
        if not os.path.exists(path) or (refresh_current and y == this_year):
            r = requests.get(MARCAP_URL.format(year=y), timeout=300); r.raise_for_status()
            if not r.content.startswith(b"PAR1"): raise ValueError(f"marcap-{y}: not parquet")
            with open(path + ".tmp", "wb") as fh: fh.write(r.content)
            os.replace(path + ".tmp", path); time.sleep(pause)
        paths.append(path)
    return paths

def load_marcap(paths):
    df = pd.concat([pd.read_parquet(p, columns=COLS) for p in paths], ignore_index=True)
    df["Date"] = df["Date"].astype("datetime64[ns]"); df["Code"] = df["Code"].astype(str)
    for c in ("Name","Market","MarketId","Dept"): df[c] = df[c].astype("category")
    return df.sort_values(["Code","Date"], kind="stable").reset_index(drop=True)

def add_adjusted(df, gap_days=20):
    df = df.copy(); g = df.groupby("Code", sort=False)
    prev_close, prev_vol, prev_date = g["Close"].shift(1), g["Volume"].shift(1), g["Date"].shift(1)
    base = df["Close"] - df["Changes"]
    df["ret"] = (df["Close"]/base - 1.0).where((base > 0) & prev_close.notna())
    f = (base/prev_close).where((base > 0) & (prev_close > 0)); f = f.where((f-1).abs() > 1e-6, 1.0).fillna(1.0)
    df["new_spell"] = prev_date.isna() | ((df["Date"] - prev_date).dt.days > gap_days)
    f = f.where(~df["new_spell"], 1.0); df.loc[df["new_spell"], "ret"] = np.nan
    df["reset_after_halt"] = (f != 1.0) & (prev_vol == 0)
    s_last = df["Stocks"].where(df["Volume"] > 0).groupby(df["Code"]).shift(1).groupby(df["Code"]).ffill()
    df["ambiguous_reset"] = df["reset_after_halt"] & (df["Stocks"] == s_last)
    raw = (df["Close"]/prev_close - 1.0).where(prev_close > 0)
    df["ret_alt"] = df["ret"].where(~df["ambiguous_reset"], raw)
    df["spell"] = df.groupby("Code", sort=False)["new_spell"].cumsum().astype("int16")
    df["sess_in_spell"] = df.groupby(["Code","spell"], sort=False).cumcount().astype("int32")
    df["_f"] = f
    rev = df.iloc[::-1].groupby(["Code","spell"], sort=False)["_f"].cumprod().iloc[::-1]
    df["adj_factor"] = (rev/df["_f"]).astype(float); df["AdjClose"] = df["Close"]*df["adj_factor"]
    return df.drop(columns="_f")

def eligible_mask(df, markets=("STK","KSQ"), common_only=True, drop_spac_reit=True, drop_admin=True,
                  min_sessions=0, min_price=0.0, exclude_codes=None, drop_foreign=False):
    m = df["MarketId"].isin(markets)
    if common_only: m &= df["Code"].str.endswith("0")
    name = df["Name"].astype(str)
    if drop_spac_reit:
        m &= ~name.str.contains(_SPAC_RE) & ~name.str.contains(_NONSTOCK_RE)
        m &= ~df["Dept"].astype(str).str.startswith("SPAC")
    if exclude_codes: m &= ~df["Code"].isin(exclude_codes)
    if drop_foreign: m &= ~df["Code"].str.startswith("9")
    if drop_admin: m &= ~df["Dept"].astype(str).str.startswith(_ADMIN_DEPT)
    if min_sessions:
        if "sess_in_spell" not in df: raise ValueError("min_sessions needs sess_in_spell from add_adjusted()")
        m &= df["sess_in_spell"] >= min_sessions
    if min_price: m &= df["Close"] >= min_price
    return m

def rolling_mean(df, col, window, min_periods=None):
    return df.groupby(["Code","spell"], sort=False)[col].transform(lambda s: s.rolling(window, min_periods=min_periods or max(1, window//2)).mean())

def last_session(df, date):
    d = df["Date"].drop_duplicates().sort_values(); d = d[d <= pd.Timestamp(date)]
    if d.empty: raise ValueError(f"no KRX session on or before {date}")
    return d.iloc[-1]

def universe_on(df, date, n, rank_col="Marcap", **elig):
    t = last_session(df, date); d = df[df["Date"] == t]
    d = d[eligible_mask(d, **elig) & (d["Volume"] > 0)]
    if d.empty: raise ValueError(f"empty universe on {t.date()}")
    return d.nlargest(n, rank_col)
